<label>Fin de la sesión<input type="datetime-local" step="1" name="end_at" value="<?= $this->text->e((new DateTimeImmutable('@'.$row['end']))->setTimezone(new DateTimeZone('America/Bogota'))->format('Y-m-d\TH:i:s')) ?>" required></label><label>Duración (segundos)<input type="number" name="duration_seconds" min="0" step="1" value="<?= (int) $row['duration_seconds'] ?>" required></label><label>Nota<textarea name="note"><?= $this->text->e($row['note']) ?></textarea></label><label>Motivo<input name="reason" required></label><button class="btn btn-blue" name="operation" value="correct">Guardar corrección</button></form></details><?php endif ?></div><?php endforeach ?>
